package com.hansraj.choptorch.service
import android.app.*;import android.content.*;import androidx.core.app.NotificationCompat;import com.hansraj.choptorch.MainActivity
object NotificationHelper {const val CHANNEL="chop_monitor";const val ID=42;fun notification(c:Context)=NotificationCompat.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.btn_star_big_on).setContentTitle("ChopTorch monitoring").setContentText("Double-chop gesture is listening").setOngoing(true).setContentIntent(PendingIntent.getActivity(c,0,Intent(c,MainActivity::class.java),PendingIntent.FLAG_IMMUTABLE)).build();fun create(c:Context){(c.getSystemService(NotificationManager::class.java)).createNotificationChannel(NotificationChannel(CHANNEL,"ChopTorch monitoring",NotificationManager.IMPORTANCE_LOW))}}
